use phx_parser_common::{identifier_pattern,parse_generic,GenericDialectConfig,ObjectSpec};use phx_sql_model::{ObjectKind,SqlModel};use phx_sql_parser_api::{ParseError,SqlDialect,SqlDialectParser};pub struct SqliteParser;impl SqlDialectParser for SqliteParser{fn dialect(&self)->SqlDialect{SqlDialect::Sqlite}fn parse(&self,s:&str,sql:&str)->Result<SqlModel,ParseError>{parse_sql(s,sql).map_err(|e|ParseError::new(SqlDialect::Sqlite,e))}}pub fn parse_sql(s:&str,sql:&str)->Result<SqlModel,String>{let id=identifier_pattern();let cfg=GenericDialectConfig{dialect:"sqlite",create_table_pattern:format!(r"(?im)^\s*CREATE\s+(?:TEMP(?:ORARY)?\s+)?TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?(?P<name>{id})\s*\("),alter_fk_pattern:None,constraint_keywords:vec!["NOT NULL","NULL","DEFAULT","PRIMARY KEY","UNIQUE","REFERENCES","CHECK","CONSTRAINT","COLLATE","GENERATED","AS"],object_specs:vec![ObjectSpec{kind:ObjectKind::View,pattern:format!(r"(?im)^\s*CREATE\s+(?:TEMP(?:ORARY)?\s+)?VIEW\s+(?:IF\s+NOT\s+EXISTS\s+)?(?P<name>{id})"),target_pattern:None},ObjectSpec{kind:ObjectKind::Trigger,pattern:format!(r"(?im)^\s*CREATE\s+(?:TEMP(?:ORARY)?\s+)?TRIGGER\s+(?:IF\s+NOT\s+EXISTS\s+)?(?P<name>{id})"),target_pattern:Some(format!(r"(?i)\bON\s+(?P<target>{id})"))},ObjectSpec{kind:ObjectKind::Index,pattern:format!(r"(?im)^\s*CREATE\s+(?:UNIQUE\s+)?INDEX\s+(?:IF\s+NOT\s+EXISTS\s+)?(?P<name>{id})"),target_pattern:Some(format!(r"(?i)\bON\s+(?P<target>{id})"))}],go_batch:false};parse_generic(s,sql,&cfg)}
